var ui=new Autodesk.Revit.UI.UIApplication(document.Application);var views=new FilteredElementCollector(document).OfClass(typeof(View3D)).Cast<View3D>().ToList();var frame=views.Single(v=>v.Name=="04 Timber and Trusses - Coordination WIP");var architecture=views.Single(v=>v.Name=="03 Building Geometry - Coordination WIP");
